<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { storeToRefs } from 'pinia'
import { useSessionStore } from './session'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from './api'
import TicketThread from './TicketThread.vue'
type Category = { id:number; parent_id:number; name:string; level:number }
type Ticket = { id:number; ticket_no:string; title:string; status:string; created_at:string; content:string; events?:{to_status:string;remark:string;created_at:string}[];images?:{id:number;name:string}[];rating?:{score:number;comment:string}|null }
type Conversation = { id:string; title:string; game_id:number|null }
type Message = { role:string; content:string; sources?:{id:number;title:string}[] }
type Hot = { rank:number; keyword:string;count:number;stat_date:string;source_type:string }
const { token }=storeToRefs(useSessionStore())
const screen=ref<'tickets'|'create'|'chat'|'hotspots'>('tickets')
const route=useRoute(), router=useRouter()
const registering=ref(false), authenticating=ref(false)
const credentials=ref({username:'',password:''})
const categories=ref<Category[]>([]), tickets=ref<Ticket[]>([]), selected=ref<Ticket|null>(null)
const conversations=ref<Conversation[]>([]), messages=ref<Message[]>([]), hotspots=ref<Hot[]>([])
const chat=ref({game_id:0,question:'',conversation_id:''})
const historyOnly=ref(false), asking=ref(false), submitting=ref(false), offset=ref(0)
const restoring=ref(!!token.value), loading=ref(false), loadFailed=ref(false), hotspotsLoading=ref(false), hotspotsFailed=ref(false), conversationsLoading=ref(false), conversationsFailed=ref(false), detailLoading=ref(false), detailFailed=ref(false), rating=ref(false), uploading=ref(false)
let generation=0, detailRequest=0, listRequest=0, conversationRequest=0
const form=ref({game_id:0,version_id:0,category_id:0,title:'',content:'',ticket_type:'CONSULT',priority:2})
const ticketFilter=ref('ALL'), ticketQuery=ref(''), ticketTotal=ref(0), ratingScore=ref(5), ratingComment=ref('')
const filteredTickets=computed(()=>tickets.value)
function selectFilter(value:string){ticketFilter.value=value;offset.value=0;selected.value=null;detailRequest++;detailLoading.value=false;detailFailed.value=false;void refresh()}
const games=computed(()=>categories.value.filter(c=>c.level===1))
const versions=computed(()=>categories.value.filter(c=>c.parent_id===form.value.game_id&&c.level===2))
const subjects=computed(()=>categories.value.filter(c=>c.parent_id===form.value.version_id&&c.level===3))
const statusLabel:Record<string,string>={PENDING:'待处理',ASSIGNED:'已接单',PROCESSING:'处理中',CLOSED:'已完成',RATED:'已评价'}
function error(e:any){
  if(e?.response?.status===401 && token.value && e?.config?.headers?.Authorization === `Bearer ${token.value}`){clearSession();ElMessage.error('登录已失效，请重新登录');return}
  const detail=e?.response?.data?.detail
  ElMessage.error(typeof detail==='string'?detail:'请求失败，请稍后重试')
}
function clearSession(){
  generation++;detailRequest++;listRequest++;conversationRequest++
  sessionStorage.removeItem('gamecs_player_token');token.value='';selected.value=null;tickets.value=[];categories.value=[];conversations.value=[];hotspots.value=[];messages.value=[];credentials.value={username:'',password:''};form.value={game_id:0,version_id:0,category_id:0,title:'',content:'',ticket_type:'CONSULT',priority:2};offset.value=0;ticketFilter.value='ALL';ticketQuery.value='';ticketTotal.value=0;ratingScore.value=5;ratingComment.value='';newChat();loading.value=false;loadFailed.value=false;hotspotsLoading.value=false;hotspotsFailed.value=false;conversationsLoading.value=false;conversationsFailed.value=false;detailLoading.value=false;detailFailed.value=false;restoring.value=false
}

// The API stores timezone-less timestamps in Asia/Shanghai; preserve that meaning.
function formatDate(value: string | null | undefined): string {
  if (!value) return '时间未知'
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)
  if (dateOnly) {
    const date = new Date(`${value}T00:00:00+08:00`)
    return Number.isNaN(date.getTime()) || new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date) !== value ? '时间未知' : value
  }
  const normalized = value.trim().replace(' ', 'T')
  const timestamp = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(normalized) ? normalized : `${normalized}+08:00`
  const date = new Date(timestamp)
  if (Number.isNaN(date.getTime())) return '时间未知'
  return new Intl.DateTimeFormat('zh-CN', {timeZone:'Asia/Shanghai', year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', hourCycle:'h23'}).format(date).replaceAll('/', '-')
}

async function refresh(){
 const gen=generation, request=++listRequest; loading.value=true;loadFailed.value=false
 try{const [a,b]=await Promise.all([api.get('/categories'),api.get('/tickets',{params:{offset:offset.value,include_total:true,status:ticketFilter.value==='ALL'?undefined:ticketFilter.value,query:ticketQuery.value}})]);if(gen!==generation||request!==listRequest)return;categories.value=a.data;tickets.value=b.data.items;ticketTotal.value=b.data.total}
 catch(e){if(gen===generation&&request===listRequest){loadFailed.value=true;error(e)}}
 finally{if(gen===generation&&request===listRequest)loading.value=false}
}
async function page(delta:number){if(loading.value)return;offset.value=Math.max(0,offset.value+delta);selected.value=null;detailRequest++;await refresh()}
async function loadHotspots(){const gen=generation;hotspotsLoading.value=true;hotspotsFailed.value=false;try{const {data}=await api.get('/hotspots');if(gen===generation)hotspots.value=data}catch(e){if(gen===generation){hotspotsFailed.value=true;error(e)}}finally{if(gen===generation)hotspotsLoading.value=false}}
async function authenticate(){if(authenticating.value)return;authenticating.value=true;try{if(registering.value)await api.post('/auth/register',credentials.value);const {data}=await api.post('/auth/login',credentials.value);clearSession();token.value=data.access_token;sessionStorage.setItem('gamecs_player_token',token.value);await refresh();if(screen.value==='chat')await loadConversations();if(screen.value==='hotspots')await loadHotspots()}catch(e){error(e)}finally{authenticating.value=false}}
async function submit(){if(submitting.value)return;if(!form.value.game_id||!form.value.version_id||!form.value.category_id){ElMessage.warning('请选择游戏、版本和问题分类');return}const gen=generation;submitting.value=true;try{const {data}=await api.post('/tickets',form.value);if(gen!==generation)return;ElMessage.success('工单已提交，可在详情中添加图片');form.value={game_id:0,version_id:0,category_id:0,title:'',content:'',ticket_type:'CONSULT',priority:2};offset.value=0;ticketFilter.value='ALL';ticketQuery.value='';await navigate('tickets');await nextTick();if(gen===generation)await details(data.id)}catch(e){if(gen===generation)error(e)}finally{submitting.value=false}}
async function details(id:number){const gen=generation, request=++detailRequest;selected.value=null;detailLoading.value=true;detailFailed.value=false;try{const {data}=await api.get(`/tickets/${id}`);if(gen===generation&&request===detailRequest)selected.value=data}catch(e){if(gen===generation&&request===detailRequest){detailFailed.value=true;error(e)}}finally{if(gen===generation&&request===detailRequest)detailLoading.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||!selected.value||uploading.value)return;if(!['image/png','image/jpeg','image/gif'].includes(file.type)||file.size>5*1024*1024){ElMessage.warning('请选择不超过 5 MB 的 PNG、JPEG 或 GIF 图片');input.value='';return}const id=selected.value.id, gen=generation;const formData=new FormData();formData.append('file',file);uploading.value=true;try{await api.post(`/tickets/${id}/images`,formData);if(gen!==generation)return;ElMessage.success('图片已上传');if(selected.value?.id===id)await details(id)}catch(e){if(gen===generation)error(e)}finally{uploading.value=false;input.value=''}}
async function download(image:{id:number;name:string}){if(!selected.value)return;const id=selected.value.id, gen=generation;try{const response=await api.get(`/tickets/${id}/images/${image.id}`,{responseType:'blob'});if(gen!==generation)return;const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download=image.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(gen===generation)error(e)}}
async function rate(){if(!selected.value||rating.value)return;const id=selected.value.id,gen=generation;rating.value=true;try{await api.post(`/tickets/${id}/rating`,{score:ratingScore.value,comment:ratingComment.value});if(gen!==generation)return;ElMessage.success('评价已提交');ratingScore.value=5;ratingComment.value='';await refresh();if(selected.value?.id===id)await details(id)}catch(e){if(gen===generation)error(e)}finally{rating.value=false}}
async function loadConversations(){const gen=generation;conversationsLoading.value=true;conversationsFailed.value=false;try{const {data}=await api.get('/agent/conversations');if(gen===generation)conversations.value=data}catch(e){if(gen===generation){conversationsFailed.value=true;error(e)}}finally{if(gen===generation)conversationsLoading.value=false}}
function newChat(){conversationRequest++;chat.value={game_id:0,question:'',conversation_id:''};messages.value=[];historyOnly.value=false}
async function openConversation(c:Conversation){const gen=generation,request=++conversationRequest;try{const {data}=await api.get(`/agent/conversations/${encodeURIComponent(c.id)}`);if(gen!==generation||request!==conversationRequest)return;messages.value=data.map((m:{role:string;content:string;sources:{id:number;title:string}[]})=>({role:m.role==='user'?'你':'客服助手',content:m.content,sources:m.sources}));chat.value={game_id:c.game_id||0,question:'',conversation_id:c.game_id?c.id:''};historyOnly.value=!c.game_id}catch(e){if(gen===generation&&request===conversationRequest)error(e)}}
function readable(text:string){return text.replace(/\*\*(.+?)\*\*/g,'$1').replace(/^\s*#{1,6}\s+/gm,'')}
async function removeConversation(c:Conversation){const gen=generation;try{await ElMessageBox.confirm('确认删除这段对话？','删除对话',{confirmButtonText:'确定',cancelButtonText:'取消'});if(gen!==generation)return;await api.delete(`/agent/conversations/${encodeURIComponent(c.id)}`);if(gen!==generation)return;if(chat.value.conversation_id===c.id)newChat();await loadConversations()}catch(e:any){if(gen===generation&&e!=='cancel'&&e!=='close')error(e)}}
async function ask(){const question=chat.value.question.trim();if(!question||!chat.value.game_id||asking.value||historyOnly.value)return;const gen=generation,request=conversationRequest;asking.value=true;try{const {data}=await api.post('/agent/chat',{game_id:chat.value.game_id,question,conversation_id:chat.value.conversation_id||null},{timeout:90000});if(gen!==generation||request!==conversationRequest)return;messages.value.push({role:'你',content:question},{role:'客服助手',content:data.answer,sources:data.sources});chat.value.question='';chat.value.conversation_id=data.conversation_id;await loadConversations()}catch(e){if(gen===generation&&request===conversationRequest)error(e)}finally{asking.value=false}}
async function navigate(value:'tickets'|'create'|'chat'|'hotspots'){await router.push({name:value})}
watch(()=>route.name, async (name)=>{if(typeof name!=='string'||!['tickets','create','chat','hotspots'].includes(name))return;screen.value=name as typeof screen.value;if(!token.value||restoring.value)return;if(name==='tickets'){selected.value=null;detailRequest++;detailLoading.value=false;detailFailed.value=false;await refresh()}if(name==='chat')await loadConversations();if(name==='hotspots')await loadHotspots()},{immediate:true})
async function logout(){const oldToken=token.value;const request=api.post('/auth/logout',null,{headers:{Authorization:`Bearer ${oldToken}`}});clearSession();void router.push({name:'tickets'});try{await request}catch{/* Local session is already cleared. */}}
async function restore(){const gen=generation;try{await api.get('/auth/me');if(gen!==generation)return;restoring.value=false;await refresh();if(gen!==generation)return;if(screen.value==='chat')await loadConversations();if(screen.value==='hotspots')await loadHotspots()}catch(e){if(gen===generation){if((e as any)?.response?.status===401){clearSession();ElMessage.error('登录已失效，请重新登录')}else{restoring.value=false;loadFailed.value=true;error(e)}}}}
if(token.value)void restore()
</script>

<template>
<div class="shell">
  <header class="topbar">
    <div class="brand" aria-label="GameCS 玩家服务中心"><img class="brand-mark" src="/assets/gamecs-mark.svg" alt=""><span><b>GAMECS</b><small>玩家服务中心</small></span></div>
    <nav v-if="token" class="nav" aria-label="主导航">
      <button v-for="item in [{id:'tickets',label:'我的工单'},{id:'create',label:'提交问题'},{id:'chat',label:'客服助手'},{id:'hotspots',label:'热点舆情'}]" :key="item.id" :class="{active:screen===item.id}" :aria-current="screen===item.id?'page':undefined" @click="navigate(item.id as typeof screen)">{{item.label}}</button>
    </nav>
    <button v-if="token" class="text-button logout" @click="logout">退出登录</button><span v-else class="top-note">夜航服务台 · 与玩家同行</span>
  </header>
  <main v-if="restoring" class="workspace"><div class="empty">正在恢复登录状态…</div></main>
  <main v-else-if="!token" class="auth">
    <section class="auth-intro"><div class="departure-board"><div class="board-title"><strong>GAMECS</strong><span>前往更好的游戏体验</span></div><div class="board-head"><span>服务</span><span>你可以在这里</span><span>目的地</span></div><div class="board-row"><b>01</b><span>提交遇到的问题</span><em>提交问题</em></div><div class="board-row"><b>02</b><span>查看问题处理进度</span><em>我的工单</em></div><div class="board-row"><b>03</b><span>向客服助手提问</span><em>客服助手</em></div><div class="board-row"><b>04</b><span>了解玩家关注的话题</span><em>热点舆情</em></div><div class="board-footer">NEXT STOP <span>✦</span> BETTER PLAY</div></div><div class="auth-tickets"><div><small>GAMECS · PLAYER SERVICE</small><strong>从问题<br>到解决</strong><p>让热爱的旅程，一直继续。</p></div><div><span>每一次求助<br>都值得被认真对待</span><small>FOR EVERY PLAYER</small></div></div></section>
    <form class="login paper" @submit.prevent="authenticate"><div class="paper-top">GAMECS <span>PLAYER SERVICE</span></div><h2>{{registering?'注册 · 开始你的旅程':'登录 · 开启你的服务旅程'}}</h2><p>{{registering?'创建账号，连接游戏服务。':'提交问题、查询进度、使用客服助手。'}}</p><label>用户名<input v-model="credentials.username" autocomplete="username" required minlength="2" placeholder="输入用户名"></label><label>密码<input v-model="credentials.password" type="password" :autocomplete="registering?'new-password':'current-password'" required minlength="6" placeholder="输入密码"></label><button class="primary" :disabled="authenticating">{{authenticating?'请稍候…':registering?'注册并登录':'登录'}} <span>→</span></button><button type="button" class="text-button" @click="registering=!registering">{{registering?'已有账号？返回登录':'还没有账号？立即注册'}}</button></form>
  </main>
  <main v-else class="workspace">
    <section v-if="screen==='tickets'" class="content"><div class="section-head"><div><p class="eyebrow">玩家服务 / 我的工单</p><h1>我的工单</h1><p>查看问题的处理进度和回复记录。</p></div><button class="primary" @click="navigate('create')">＋ 提交问题</button></div>
      <div class="ticket-workspace"><aside class="ticket-index"><div class="index-title">◈　我的工单</div><div class="index-count">{{ticketTotal}} <span>符合条件</span></div><button v-for="filter in [{id:'ALL',name:'全部'},{id:'PENDING',name:'待处理'},{id:'ASSIGNED',name:'已接单'},{id:'PROCESSING',name:'处理中'},{id:'CLOSED',name:'已完成'},{id:'RATED',name:'已评价'}]" :key="filter.id" :class="{active:ticketFilter===filter.id}" @click="selectFilter(filter.id)"><span>{{filter.name}}</span></button><div class="index-note">GAMECS<br>PLAYER SUPPORT<br><span>下一站，更好的游戏体验</span></div></aside><div class="ticket-column"><div class="list-head"><strong>服务记录</strong><span>共 {{ticketTotal}} 条</span></div><form class="ticket-search" @submit.prevent="offset=0;refresh()"><label>搜索工单<input v-model="ticketQuery" maxlength="200" placeholder="工单编号或标题"></label><button class="outline">搜索</button></form><div v-if="loading" class="empty">正在加载工单…</div><div v-else-if="loadFailed" class="empty">工单加载失败。<button class="text-button" @click="refresh">重试</button></div><div v-else-if="filteredTickets.length" class="ticket-list"><button v-for="ticket in filteredTickets" :key="ticket.id" class="ticket" :class="{selected:selected?.id===ticket.id}" @click="details(ticket.id)"><span class="ticket-main"><small>{{ticket.ticket_no}}</small><strong>{{ticket.title}}</strong><span>{{formatDate(ticket.created_at)}}</span></span><span class="status" :class="ticket.status.toLowerCase()">{{statusLabel[ticket.status]||ticket.status}}</span><span class="ticket-arrow">›</span></button></div><div v-else class="empty">当前筛选下没有工单。遇到问题时，可以提交新问题。</div><div class="pager"><button class="text-button" :disabled="offset===0" @click="page(-50)">← 上一页</button><button class="text-button" :disabled="offset+50>=ticketTotal" @click="page(50)">下一页 →</button></div></div>
      <aside class="detail paper" aria-live="polite"><div v-if="detailLoading" class="detail-empty">正在加载工单详情…</div><div v-else-if="detailFailed" class="detail-empty">工单详情加载失败，请重新选择工单。</div><template v-else-if="selected"><div class="paper-top">工单详情 <span>{{selected.ticket_no}}</span></div><h2>{{selected.title}}</h2><span class="status">{{statusLabel[selected.status]||selected.status}}</span><p class="detail-content">{{selected.content}}</p><h3>图片附件</h3><p v-if="!selected.images?.length" class="muted">暂无附件</p><p v-for="image in selected.images" :key="image.id"><button class="text-button" @click="download(image)">{{image.name}} ↓</button></p><label class="upload">添加图片<input type="file" accept="image/png,image/jpeg,image/gif" :disabled="uploading" @change="upload"></label><TicketThread :ticket-id="selected.id" :status="selected.status" :can-reply="true" :events="selected.events"/><p v-if="selected.rating">评价：{{selected.rating.score}} / 5　{{selected.rating.comment}}</p><form v-if="selected.status==='CLOSED'" @submit.prevent="rate"><label>满意度<select v-model.number="ratingScore"><option v-for="n in 5" :key="n" :value="n">{{n}} 分</option></select></label><label>评价内容（可选）<textarea v-model="ratingComment" maxlength="500" rows="2"></textarea></label><button class="primary" :disabled="rating">提交评价并确认解决</button></form></template><div v-else class="detail-empty"><span>✦</span><h2>选择一条工单</h2><p>在这里查看处理记录和附件。</p></div></aside></div>
    </section>
    <section v-else-if="screen==='create'" class="content"><div class="section-head"><div><p class="eyebrow">玩家服务 / 提交问题</p><h1>提交问题</h1><p>详细描述遇到的情况，帮助我们更快处理。</p></div></div><div v-if="loadFailed" class="empty">游戏数据加载失败。<button class="text-button" @click="refresh">重试</button></div><div class="form-layout"><form class="ticket-form paper" @submit.prevent="submit"><div class="form-banner"><small>GAMECS　 TICKET OFFICE</small><h2>提交问题</h2><p>一张工单，通往更好的游戏体验</p></div><div class="form-grid"><label>游戏<select v-model.number="form.game_id" @change="form.version_id=0;form.category_id=0"><option :value="0" disabled>请选择游戏</option><option v-for="c in games" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>版本<select v-model.number="form.version_id" @change="form.category_id=0"><option :value="0" disabled>请选择版本</option><option v-for="c in versions" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>问题分类<select v-model.number="form.category_id"><option :value="0" disabled>请选择分类</option><option v-for="c in subjects" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>问题类型<select v-model="form.ticket_type"><option value="CONSULT">咨询</option><option value="BUG">故障</option><option value="ADVICE">建议</option><option value="COMPLAINT">投诉</option></select></label></div><label>问题标题<input v-model="form.title" required maxlength="200" placeholder="简要描述遇到的问题"></label><label>详细描述<textarea v-model="form.content" required rows="7" maxlength="10000" placeholder="请描述发生的情况和尝试过的操作"></textarea></label><button class="primary" :disabled="submitting">{{submitting?'正在提交…':'提交工单'}} <span>→</span></button></form><aside class="guide"><p class="eyebrow">服务指引</p><h2>让我们更了解问题</h2><ol><li>选择遇到问题的游戏和版本</li><li>填写清晰的问题标题</li><li>描述发生的情况和操作步骤</li></ol><p>提交后，可在工单详情中添加图片。</p></aside></div></section>
    <section v-else-if="screen==='chat'" class="content"><div class="section-head"><div><p class="eyebrow">玩家服务 / 客服助手</p><h1>客服助手</h1><p>选择游戏，向助手描述你遇到的问题。</p></div><button class="outline" @click="newChat">＋ 新对话</button></div><div v-if="loadFailed" class="empty">游戏数据加载失败。<button class="text-button" @click="refresh">重试</button></div><div class="chat-layout"><aside class="chat-history"><div class="list-head"><strong>历史对话</strong><button type="button" class="outline" @click="newChat">＋ 新对话</button></div><p v-if="conversationsLoading" class="muted">正在加载对话…</p><p v-else-if="conversationsFailed" class="muted">对话加载失败。<button class="text-button" @click="loadConversations">重试</button></p><div v-for="conversation in conversations" :key="conversation.id" class="history-row"><button class="history-title" @click="openConversation(conversation)">{{conversation.title}}</button><button class="text-button" :aria-label="'删除对话 '+conversation.title" @click="removeConversation(conversation)">删除</button></div><p v-if="!conversationsLoading && !conversationsFailed && !conversations.length" class="muted">暂无历史对话</p></aside><form class="chat-panel" @submit.prevent="ask"><label class="game-select">选择游戏<select v-model.number="chat.game_id" :disabled="!!chat.conversation_id || historyOnly" @change="messages=[]"><option :value="0" disabled>请选择游戏</option><option v-for="c in games" :key="c.id" :value="c.id">{{c.name}}</option></select></label><p v-if="historyOnly" class="muted">这段旧对话没有记录所属游戏，可查看历史。请新建对话继续提问。</p><div class="messages" aria-live="polite"><div v-for="(message,index) in messages" :key="index" class="message" :class="{user:message.role==='你'}"><small>{{message.role}}</small><div class="message-body"><span class="message-text">{{readable(message.content)}}</span><p v-if="message.sources?.length" class="sources">参考：{{message.sources.map(s=>s.title).join('、')}}</p></div></div><div v-if="!messages.length" class="chat-empty"><span>✦</span><p>告诉我你遇到的问题，我们一起寻找答案。</p></div></div><label>你的问题<textarea v-model="chat.question" rows="3" required maxlength="4000" :disabled="historyOnly" placeholder="输入问题"></textarea></label><button class="primary send" :disabled="asking||historyOnly||!chat.game_id">{{asking?'正在回复…':'发送问题'}} →</button></form></div></section>
    <section v-else class="content"><div class="section-head"><div><p class="eyebrow">玩家服务 / 热点舆情</p><h1>热点舆情</h1><p>查看玩家关注的问题。</p></div></div><div class="hot-layout"><aside class="hot-index"><strong>今日热点</strong><p>关注玩家的问题，<br>听见更多声音。</p><div class="hot-track">✦<br>│<br>◉<br>│<br>✦</div><small>GAMECS / PLAYER SERVICE</small></aside><div class="hot-list"><p v-if="hotspotsLoading" class="empty">正在加载热点…</p><p v-else-if="hotspotsFailed" class="empty">热点加载失败。<button class="text-button" @click="loadHotspots">重试</button></p><div v-for="hot in hotspots" :key="hot.rank" class="hot-row"><span class="rank">{{String(hot.rank).padStart(2,'0')}}</span><strong>{{hot.keyword}}</strong><span>{{hot.count}} 条</span><small>{{formatDate(hot.stat_date)}} · {{hot.source_type==='fallback'?'历史数据':'当日统计'}}</small></div><p v-if="!hotspotsLoading && !hotspotsFailed && !hotspots.length" class="empty">暂无热点数据。</p></div><aside class="hot-guide"><strong>数据说明</strong><p>展示平台统计的热点关键词与数量。</p><p>每条记录标注统计日期与数据来源。</p><div class="hot-track">✦　NEXT STOP<br>　　BETTER PLAY</div></aside></div></section>
  </main>
</div>
</template>
